def max_buckets(grid, capacity):
    bucket_count = 0
    bucket_capacity = capacity
    bucket_used = 0
    for row in grid:
        for cell in row:
            if cell == 1:
                bucket_used += 1
                while bucket_used >= bucket_capacity:
                    bucket_used -= bucket_capacity
                    bucket_count += 1
    return bucket_count

def max_buckets(grid, capacity):
    bucket_count = 0
    bucket_capacity = capacity
    bucket_used = 0
    for row in grid:
        for cell in row:
            if cell == 1:
                if bucket_used + bucket_capacity <= capacity:
                    bucket_used += bucket_capacity
                    bucket_count += 1
                else:
                    bucket_count += math.ceil((bucket_capacity - bucket_used) / (capacity - bucket_capacity))
                    bucket_used = capacity
                    bucket_count += 1
                bucket_capacity = capacity
            else:
                bucket_capacity = capacity
    return bucket_count

