def tribonacci(n):
    if n == 0:
        return [3]
    elif n == 1:
        return [3, 3]
    elif n == 2:
        return [3, 3, 2]
    else:
        seq = [3, 3, 2]
        for i in range(3, n):
            if i % 2 == 0:
                seq.append(seq[i//2] + seq[i//2 - 1] + seq[i//2 + 1])
            else:
                seq.append(seq[i-1] + seq[i-2] + seq[i-3])
        return seq
return tribonacci(n)

