def shift_down(c):
    """Helper function to shift a character down by two places."""
    ch = ord(c)
    if ch >= ord('a') and ch <= ord('z'):
        return chr((ch - ord('a') - 2) % 26 + ord('a'))
    elif ch >= ord('A') and ch <= ord('Z'):
        return chr((ch - ord('A') - 2) % 26 + ord('A'))
    else:
        return c

